    #[test]
    fn sh251c_getter_landingpad_cleanup_not_forward_ctor() {
        // SH251b CORRECTION (SH251c): 0x102b9eca0 is NOT an indirect-only "next-unsynthesized"
        // ctor. TRUE entry = 0x2b9ec9c (`paciasp`); exec seg has 64,748 `bl 0x2b9ec9c` + ZERO
        // `bl 0x2b9eca0`. Two callers in PlayerGui getter 0x10201fce0 are EXCEPTION LANDING PADS
        // (each preceded by a __cxa cleanup bl): NULL-this crash @0x102b9ecbc = unwind teardown
        // (spawned-thread SIGTRAP), not Route-B construction. Pin true entry + 2 landing pads + bls;
        // assert bl-imm26 targets 0x2b9ec9c so +4 drift fails loudly.
        fn bl_target(pc: usize, img: &[u8]) -> u64 {
            let w = u32::from_le_bytes([img[pc], img[pc + 1], img[pc + 2], img[pc + 3]]);
            assert_eq!(w & 0xfc00_0000, 0x9400_0000, "word at 0x{pc:x} must be a BL");
            let imm26 = (w & 0x3ff_ffff) as i64;
            let imm26 = if imm26 & 0x200_0000 != 0 { imm26 - 0x400_0000 } else { imm26 };
            (pc as i64 + imm26 * 4) as u64
        }
        let ep = 0x2b9ec9c; // true paciasp entry (SH251b pinned 0x2b9eca0, +4 too late)
        let lpad_1 = 0x201fda0; // getter landing pad bl 0x2b9ec9c
        let lpad_2 = 0x201fe48; // getter landing pad bl 0x2b9ec9c
        let cxa_1 = 0x201fd98; // bl 284cfbc (__cxa cleanup) preceding lpad_1
        let cxa_2 = 0x201fe40; // bl 5fb25e0 (__cxa cleanup) preceding lpad_2
        for &pc in &[ep, lpad_1, lpad_2, cxa_1, cxa_2] {
            assert_eq!(pc & 3, 0, "site 0x{pc:x} must be 4-aligned");
        }
        let p = std::path::Path::new("/home/hermes-worker/.cache/open-sober/robbox/libroblox.so");
        if p.exists() {
            let img = std::fs::read(p).expect("read real libroblox.so");
            // true entry = paciasp
            let epw = u32::from_le_bytes([img[ep], img[ep + 1], img[ep + 2], img[ep + 3]]);
            assert_eq!(epw, 0xd503233f, "0x2b9ec9c must be paciasp (true entry)");
            // both landing-pad bls must target the paciasp entry 0x2b9ec9c
            assert_eq!(bl_target(lpad_1, &img), ep as u64, "lpad_1 must bl 0x2b9ec9c");
            assert_eq!(bl_target(lpad_2, &img), ep as u64, "lpad_2 must bl 0x2b9ec9c");
            // their preceding bls are the __cxa cleanup helpers (NOT to 0x2b9ec9c)
            let t1 = bl_target(cxa_1, &img);
            assert_ne!(t1, ep as u64, "cxa_1 must not target the helper entry");
            assert_ne!(t1, 0x2b9eca0, "cxa_1 must not target 0x2b9eca0");
            let t2 = bl_target(cxa_2, &img);
            assert_ne!(t2, ep as u64, "cxa_2 must not target the helper entry");
        } else {
            eprintln!("sh251c real-image guard: no real libroblox.so, skipping");
        }
    }
    #[test]
    fn sh252_resolver_map_has_no_lazy_static_ctor() {
        // SH252 (Route-B class-registry closure): resolver map 0x106dca0e70 (name->classid,
        // getService 0x105e09bc8 -> resolver 0x2373cec) builds ONLY in-ladder registrar
        // 0x2208ae8 over SOURCE vector 0x6dca0ea8 (SH193/194/207). Exec [0x0,0x62d8190)
        // lazy-static sweep: 8,378 bl __cxa_guard_acquire, none constructs 0x6dca0e70.
        // => NO lazy-static ctor; only the bulk registrar. Drift fails loudly. skip-if-absent.
        const PAGE: u64 = 0x6dca000;
        const RESOLVER_OFF: u64 = 0xe70;
        const GUARD: u64 = 0x284ce54; // __cxa_guard_acquire (file vaddr)
        const XEND: u64 = 0x62d8190; // exec segment end (file vaddr==offset)
        fn bl_target(pc: usize, img: &[u8]) -> u64 {
            let w = u32::from_le_bytes([img[pc], img[pc + 1], img[pc + 2], img[pc + 3]]);
            assert_eq!(w & 0xfc00_0000, 0x9400_0000, "0x{pc:x} must be BL");
            let imm26 = (w & 0x3ff_ffff) as i64;
            let imm26 = if imm26 & 0x200_0000 != 0 { imm26 - 0x400_0000 } else { imm26 };
            (pc as i64 + imm26 * 4) as u64
        }
        fn adrp_page(pc: u64, w: u32) -> Option<(u64, u64)> {
            // returns (rd, page) if word is `adrp xRd, page`
            if w >> 31 != 1 || ((w >> 29) & 3) != 2 || ((w >> 24) & 0x1f) != 0b10000 {
                return None;
            }
            let rd = (w & 0x1f) as u64;
            let imm = (((w >> 5) & 0x7ffff) << 2) | ((w >> 29) & 3);
            let imm = imm as i64;
            let imm = if imm & (1i64 << 20) != 0 { imm - (1i64 << 21) } else { imm };
            let pagebase = (pc & !0xfff) as i64 + imm * 4096;
            Some((rd, pagebase as u64))
        }
        fn add_imm12(page: u64, w: u32) -> Option<u64> {
            // `add xD,xD,#imm12` (64-bit ADD-immediate, 0x91000000 family). Fixed bits:
            // sf=1, op=0, S=0, 28:23=100010 -> (w>>23)&0x7f == 0b0100010 (0x22), sh(bit22)
            // usually 0 for the registry adrp+add pairs. effective = base + imm12<<(12*sh).
            if w >> 31 != 1 || ((w >> 23) & 0x7f) != 0b0100010 {
                return None;
            }
            let sh = (w >> 22) & 3;
            let imm12 = ((w >> 10) & 0xfff) as u64;
            Some(page + imm12 * (1 << (12 * sh as u32)))
        }
        // The one lazy-static in the registrar region (0x22088xx) constructs 0x6dcaee0,
        // NOT the resolver 0xe70 - pin it drift fails before any stale re-classification.
        let p = std::path::Path::new("/home/hermes-worker/.cache/open-sober/robbox/libroblox.so");
        if p.exists() {
            let img = std::fs::read(p).expect("read real libroblox.so");
            // (a) full sweep: collect every `adrp 0x6dca000 + add #0xe70` -> resolver-map
            // forming site. MEASURED via objdump: exactly 2 - 0x2208b10 (bulk registrar
            // 0x2208ae8's dest-map pointer) and 0x2208be4 (same registrar, re-load after the
            // insert). BOTH live inside nativeGameGlobalInit's registrar region. There is NO
            // standalone lazy-static ctor for it: every resolver-forming site is in
            // [0x2208418, 0x2208cf8) (the in-ladder header default-construct + registrar body).
            let mut sites = Vec::<u64>::new();
            let mut pc = 0usize;
            while pc + 8 <= XEND as usize {
                let w0 = u32::from_le_bytes([img[pc], img[pc + 1], img[pc + 2], img[pc + 3]]);
                let w1 = u32::from_le_bytes([img[pc + 4], img[pc + 5], img[pc + 6], img[pc + 7]]);
                if let Some((rd0, page)) = adrp_page(pc as u64, w0) {
                    if page == PAGE {
                        if let Some(eff) = add_imm12(page, w1) {
                            if w1 & 0x1f == rd0 as u32 && (w1 >> 5) & 0x1f == rd0 as u32 {
                                if eff == PAGE + RESOLVER_OFF {
                                    sites.push(pc as u64);
                                }
                            }
                        }
                    }
                }
                pc += 4;
            }
            // objdump-verified complete list of resolver-map-forming `adrp 6dca000 + add #0xe70` sites
            // (every exec word, 11): (i) in-ladder default-construct 0x220841c + bulk registrar
            // 0x2208b10/0x2208be0/0x2208c9c; (ii) 7 readers (0x25f8fd8, 0x28442c8, 0x31fcac4,
            // 0x3ceca04/0x3cecd6c, 0x4894100, 0x4b547f8). NONE lazy-static ctor - built only
            // in-ladder from SOURCE 0x6dca0ea8 (SH193/194/207). Any added ctor/reader fails loudly.
            let expect: [u64; 11] = [
                0x220841c,
                0x2208b10,
                0x2208be0,
                0x2208c9c,
                0x25f8fd8,
                0x28442c8,
                0x31fcac4,
                0x3ceca04,
                0x3cecd6c,
                0x4894100,
                0x4b547f8,
            ];
            assert_eq!(
                sites.len(),
                expect.len(),
                "resolver-map-forming adrp+add site count (got {sites:#x?}) must match objdump's {expect:?}"
            );
            for (i, e) in expect.iter().enumerate() {
                assert_eq!(sites[i], *e, "resolver-forming site {i} must be {e:#x}");
            }
            // (b): NO lazy-static ctor WRITES the resolver header. A true lazy-static ctor
            // would store (str/stp) the map object at PAGE+0xe70..+0xea0 (the 48-byte
            // __bucket_list_/state header, exactly what in-ladder default-construct
            // 0x2208418-0x2208434 does). The 0x25f8fb8 guard ctor FORMS the addr but only
            // passes &resolver to READ-ONLY probe 0x2373cec - never stores. Sweep every
            // __cxa_guard_acquire ctor body for a store into [PAGE+0xe70,PAGE+0xea0).
            let mut guard_sites: u64 = 0;
            let mut ctor_header_write: Vec<u64> = Vec::new();
            let mut pc = 0usize;
            while pc + 4 <= XEND as usize {
                let w = u32::from_le_bytes([img[pc], img[pc + 1], img[pc + 2], img[pc + 3]]);
                if (w & 0xfc00_0000) == 0x9400_0000 && bl_target(pc, &img) == GUARD {
                    guard_sites += 1;
                    let end = (pc + 64 * 4).min(XEND as usize);
                    // find each forming pair and any following store in that window
                    let mut q = pc + 4;
                    while q + 8 <= end {
                        let w0 = u32::from_le_bytes([img[q], img[q + 1], img[q + 2], img[q + 3]]);
                        let w1 = u32::from_le_bytes(
                            [img[q + 4], img[q + 5], img[q + 6], img[q + 7]],
                        );
                        if let Some((rd0, pg)) = adrp_page(q as u64, w0) {
                            if pg == PAGE {
                                if let Some(eff) = add_imm12(pg, w1) {
                                    if (w1 & 0x1f) == rd0 as u32 && (w1 >> 5) & 0x1f == rd0 as u32
                                        && eff == PAGE + RESOLVER_OFF
                                    {
                                        // formed &resolver into rd0 - look for a store in
                                        // the next ~16 insns to [rd0, +imm] in header range
                                        let mut s = q + 8;
                                        let se = (q + 16 * 4).min(end);
                                        while s < se {
                                            let ws =
                                                u32::from_le_bytes([img[s], img[s + 1], img[s + 2], img[s + 3]]);
                                            // STR X (unsigned imm, 64-bit): 0xf9000000 head only (0xf9400000 is LDR else)
                                            let str_x = (0xffc00000 & ws) == 0xf9000000;
                                            // STP X: 0xa9000000-family (unsigned imm)
                                            let stp_x = (0xffc00000 & ws) == 0xa9000000;
                                            // STR Q: 0x3d800000 head only (0x3dc00000 is LDR Q)
                                            let str_q = (0xffc00000 & ws) == 0x3d800000;
                                            if str_x || stp_x || str_q {
                                                let rn = (ws >> 5) & 0x1f;
                                                let imm = (ws >> 10) & 0xfff;
                                                let scale = if str_q { 16u64 } else { 8u64 };
                                                let target =
                                                    RESOLVER_OFF.wrapping_add((imm as u64) * scale);
                                                if rn as u64 == rd0 && (RESOLVER_OFF..RESOLVER_OFF + 0x30).contains(&target)
                                                {
                                                    ctor_header_write.push(s as u64);
                                                }
                                            }
                                            s += 4;
                                        }
                                    }
                                }
                            }
                        }
                        q += 4;
                    }
                }
                pc += 4;
            }
            assert!(
                guard_sites >= 8378 / 2,
                "swept {guard_sites} __cxa_guard_acquire sites (expected ~8,378 whole-exec)"
            );
            assert!(
                ctor_header_write.is_empty(),
                "no __cxa_guard_acquire ctor may WRITE the resolver-map header (got {ctor_header_write:?}) — a lazy-static ctor would load &resolver then store into it; none does (only the read-only probe 0x2373cec at 0x25f8fb8 touches the address, which never stores)"
            );
            eprintln!(
                "sh252: {n} resolver-forming adrp+add sites (objdump-pinned list of {k}), {g} guard_acquire sites swept, 0 lazy-static ctor WRITES the resolver-map header",
                n = sites.len(),
                k = expect.len(),
                g = guard_sites
            );
        } else {
            eprintln!("sh252 real-image guard: no real libroblox.so, skipping");
        }
    }
    #[test]
    fn sh200_v2_dispatch_window_materializes_obj_and_nops_to_blr() {
        // SH200 V2-init dispatch window (fn 0x6251e0c etc.): the first 4 slots
        // load the stable object into x0, the rest are nops (killing the
        // past-0x60-vtable `blr`); the length is (blr-start)/4+1. Round-trip the
        // object immediates ( x0 movz/movk, no `|8` GPR suffix).
        let obj: u64 = 0x5a_b3c4_d5e6_f708;
        let w = sh200_v2_dispatch_window(obj, 9);
        assert_eq!(w.len(), 9);
        // slot0 movz x0,#0xf708 (hw0, x0 rd=0)
        assert_eq!(w[0], 0xD280_0000u32 | ((0xf708u32) << 5));
        // slot1-3 movk x0 hw1/2/3 (obj = 0x5a:b3c4:d5e6:f708)
        assert_eq!(w[1], 0xF2A0_0000u32 | ((0xd5e6u32) << 5));
        assert_eq!(w[2], 0xF2C0_0000u32 | ((0xb3c4u32) << 5));
        assert_eq!(w[3], 0xF2E0_0000u32 | ((0x5au32) << 5));
        // slots 4..8 are nops
        for i in 4..9 {
            assert_eq!(w[i], 0xd503_201fu32, "slot {i} must be nop");
        }
        let lo = (w[0] >> 5) & 0xffff;
        let _16 = (w[1] >> 5) & 0xffff;
        let _32 = (w[2] >> 5) & 0xffff;
        let _48 = (w[3] >> 5) & 0xffff;
        let rebuilt = (lo as u64) | ((_16 as u64) << 16) | ((_32 as u64) << 32) | ((_48 as u64) << 48);
        assert_eq!(rebuilt, obj, "movz/movk round-trip must reconstruct obj");
        // a site with only 4 slots (= exactly movz+3 movk, blr immediately after)
        let w4 = sh200_v2_dispatch_window(obj, 4);
        assert_eq!(w4.len(), 4);
        for i in 0..4 {
            assert_eq!(w4[i], w[i], "first 4 slots identical regardless of length");
        }
    }
    #[test]
    fn sh201_v2_family_scan_precise_discriminator() {
        // Synthesize a minimal image with ONE genuine objB-getter dispatch site
        // and one genuine in-band N<0xf0 dispatch (which must NOT be matched).
        // Encode a `bl 0x6249eb8` at link 0x100 (byte offset 0x100).
        let make_bl = |pc: u64, target: u64| -> u32 {
            // AArch64 B/BL imm26 = (target - pc)/4 (PC = branch addr itself)
            let off = target.wrapping_sub(pc);
            let imm26 = ((off >> 2) as u32) & 0x3ff_ffff;
            0x9400_0000u32 | imm26
        };
        let mut img = Vec::<u8>::new();
        // helper: append a u32 word
        fn w(img: &mut Vec<u8>, x: u32) {
            img.extend_from_slice(&x.to_le_bytes());
        }
        // - decoys @ link 0x0 (no getter prefix; must NOT match) ---
        // in-band ldr x8,[x8,#0x40] (0x40<0x60) then blr, no getter
        let decoy_ldr_hi = 0xf940_0000 | (0x40u32 / 8 << 10) | (8 << 5) | 8; // ldr x8,[x8,#0x40]
        w(&mut img, decoy_ldr_hi);
        w(&mut img, SH201_BLR_X8); // blr (no preceeding getter)
        // another decoy: past-slot ldr x8,[x8,#0x70] + blr but NO getter
        let decoy_past = 0xf940_0000 | (0x70u32 / 8 << 10) | (8 << 5) | 8; // ldr x8,[x8,#0x70] (>=0x60)
        w(&mut img, decoy_past);
        w(&mut img, SH201_BLR_X8);
        // pad genuine block starts at 0x100
        while img.len() < 0x100 {
            w(&mut img, 0);
        }
        // - genuine site @ link 0x100 ---
        // bl 0x6249eb8 (objB getter) @0x100
        w(&mut img, make_bl(0x100, SH201_OBJ_GETTER));
        // ldr x8,[x0] @0x104 (0xf9400008)
        w(&mut img, SH201_LDR_X8_X0);
        // ldr x8,[x8,#0x70] (past 0x60)@0x108
        let imm12 = 0x70u32 / 8; // 14
        w(&mut img, 0xf940_0000 | (imm12 << 10) | (8 << 5) | 8);
        // blr x8 @0x10c
        w(&mut img, SH201_BLR_X8);
        let sites = sh201_v2_family_scan(&img);
        // exactly the one genuine site: (start=0x104, blr=0x10c)
        assert_eq!(sites.len(), 1, "only the getter-gated past-0x60 site matches, got {sites:?}");
        assert_eq!(sites[0], (0x104, 0x10c));
    }

